  }

  while (!q.empty()) {
    auto [x,y,ch] = q.front();
    q.pop();

    // If we've reached the end of our path, print it and return
    if (ch != '\0' && dart_str.size() > 4) {
      cout << dart_str << endl;
      return 0;
    }

    // Try each direction from this point
    for (auto dir : dirs) {
      int nx = x + get<0>(dir);
      int ny = y + get<1>(dir);

      // Check if next cell is in bounds
