  String dartCode = '''
int main() {
    print('Hello, World!');
}''';

  List<String> lines = dartCode.split('\n').map((e) => e.trim()).toList();

  for (var line in lines) {
      if (line.isEmpty || line.startsWith('//')) continue; // Skip empty or comment lines

      String trimmedLine = line.trim().replaceAll(r'\/\*.*?\*\/', '').trim(); // Remove inline comments

      int index = trimmedLine.indexOf('{');
      while (index != -1) {
          int endIndex = trimmedLine.lastIndexOf('}', index);
          if (endIndex == -1) break; // No matching '}' found

          bool hasBrackets = false;
          for (int i = index + 1; i < endIndex; i++) {
              char c = trimmedLine[i];
              if ((c >= 'A' && c <= 'Z') || 
                  (c >= 'a' && c <= 'z') || 
                  (c >= '0' && c <= '9') || 
                  c == '_' || 
                  c == '$') {
                  hasBrackets = true;
                  break;
              }
          }

          if (!hasBrackets) {
              System.out.println(trimmedLine.substring(index, endIndex));
              break;
          } else {
              index = trimmedLine.indexOf('{', index + 1); // Search next '{' after current one
          }
      }
  }
}

