BigInt modPow(BigInt a, BigInt b, BigInt m) {
  if (b == BigInt.zero) return BigInt.one;
  else if (b.isEven) {
    var y = modPow(a, b ~/ 2, m);
    return (y * y) % m;
  } else {
    return (a * modPow(a, b - 1, m)) % m;
  }
}

