bool dfs(int node, List<List<Edge>> graph, bool[] visited) {
  visited[node] = true;

  for (var edge : graph[node]) {
    int neighbor = edge.dest;

    if (edge.isUndirected && !visited[neighbor]) {
      visited[neighbor] = true;

      if (!dfs(neighbor, graph, visited)) {
        return false;
      }
    } else if (edge.isDirected && !visited[neighbor]) {
      if (!dfs(neighbor, graph, visited)) {
        return false;
      }
    }
  }

  return true;
}

