void bronKerbosch(Set r, Set p, Set x) {
  // Base case: if the pivot set is empty and there are no candidates in R or X, we have a maximal independent set.
  if (p.isEmpty && !r.containsAll(x)) return;

  // Choose a vertex u from P.
  var u = p.firstWhere((e) => e != null);

  // For each neighbor v of u that belongs to P \ X, add {u} ∪ N(v) ∩ P as a new independent set.
  for (var v in p.where((e) => e != null).toList()) {
    var w = neighborsOf(u)[v];
    bronKerbosch(r.add(w), p.subtract({w}), x.remove(w));
    r.remove(w);
  }

  // Remove all vertices in P ∪ X adjacent to u from P and X.
  p.removeAll(neighborsOf(u));
  x.addAll(p);
  p.clear();
}

