    if (adjList[source] == null || adjList[dest] == null) return;
    adjList[source].add(Edge(source, dest, 2.0 * Math.sqrt(dest - source)));
  }

  bool hasPathFromTo(int start, int end) => _hasPath(start, [], end);

  bool _hasPath(int node, Set<int> visited, int targetNode) {
    visited.add(node);
    if (node == targetNode) return true;
    for (var edge in adjList[node]) {
      if (!visited.contains(edge.to)) {
        if (_hasPath(edge.to, visited, targetNode)) return true;
      }
    }
    return false;
  }

  double dijkstra(int start, int targetNode) {
    if (!hasPathFromTo(start, targetNode)) return -1;
    var distanceMap = {};
    queue.Enqueue((start, 0.0));
    while (!queue.isEmpty()) {
      var pair = queue.Dequeue();
      var u = pair.$1;
      var d = pair.$2;
      if (!distanceMap.containsKey(u)) distanceMap[u] = d;
      for (var e in adjList[u]) {
        var v = e.to;
        var alt = d + e.weight;
        if (!distanceMap.containsKey(v) && alt < distanceMap[v]!) {
          distanceMap[v] = alt;
          queue.Enqueue((v, alt));
        }
      }
    }
    return distanceMap[targetNode];
  }
}

